-- Bo 30 tu chu de AIRPORT. Tu co the thuoc nhieu bai (lesson_vocab n-n).
INSERT INTO lessons (title, sub_title, type, icon, sort_order)
SELECT 'Sân bay & du lịch (30 từ)', 'Airport & Travel · 30 từ có hình', 'vocab', 'flight', 101
WHERE NOT EXISTS (SELECT 1 FROM lessons WHERE title = 'Sân bay & du lịch (30 từ)');
